--
-- Table structure for table `alta`
--

DROP TABLE IF EXISTS `alta`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `alta` (
  `id_alta` int(11) NOT NULL AUTO_INCREMENT,
  `id_atendimento` int(11) NOT NULL,
  `id_funcionario` int(11) NOT NULL,
  `data_hora` datetime NOT NULL DEFAULT current_timestamp(),
  `tipo` char(1) NOT NULL,
  `cid_final` varchar(10) DEFAULT NULL,
  `orientacoes` text DEFAULT NULL,
  PRIMARY KEY (`id_alta`),
  UNIQUE KEY `id_atendimento` (`id_atendimento`),
  KEY `fk_alta_funcionario` (`id_funcionario`),
  KEY `idx_alta_tipo_cid_atend` (`tipo`,`cid_final`,`id_atendimento`),
  CONSTRAINT `fk_alta_atendimento` FOREIGN KEY (`id_atendimento`) REFERENCES `atendimento` (`id_atendimento`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_alta_funcionario` FOREIGN KEY (`id_funcionario`) REFERENCES `funcionario` (`id_funcionario`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `ck_alta_tipo` CHECK (`tipo` in ('M','P','T','O','E'))
) ENGINE=InnoDB AUTO_INCREMENT=2168 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

