--
-- Table structure for table `atendimento`
--

DROP TABLE IF EXISTS `atendimento`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `atendimento` (
  `id_atendimento` int(11) NOT NULL AUTO_INCREMENT,
  `id_paciente` int(11) DEFAULT NULL,
  `id_cadastro_provisorio` int(11) DEFAULT NULL,
  `id_funcionario` int(11) NOT NULL,
  `id_status` int(11) NOT NULL,
  `id_local` int(11) DEFAULT NULL,
  `data_hora_entrada` datetime NOT NULL DEFAULT current_timestamp(),
  `tipo_entrada` char(1) NOT NULL,
  `queixa_principal` varchar(255) NOT NULL,
  PRIMARY KEY (`id_atendimento`),
  UNIQUE KEY `id_cadastro_provisorio` (`id_cadastro_provisorio`),
  KEY `fk_atendimento_funcionario` (`id_funcionario`),
  KEY `fk_atendimento_status` (`id_status`),
  KEY `fk_atendimento_local` (`id_local`),
  KEY `idx_atendimento_paciente_entrada` (`id_paciente`,`data_hora_entrada`),
  KEY `idx_atendimento_entrada_tipo` (`data_hora_entrada`,`tipo_entrada`),
  CONSTRAINT `fk_atendimento_cadastro_provisorio` FOREIGN KEY (`id_cadastro_provisorio`) REFERENCES `cadastro_provisorio` (`id_cadastro_provisorio`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_atendimento_funcionario` FOREIGN KEY (`id_funcionario`) REFERENCES `funcionario` (`id_funcionario`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_atendimento_local` FOREIGN KEY (`id_local`) REFERENCES `local` (`id_local`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_atendimento_paciente` FOREIGN KEY (`id_paciente`) REFERENCES `paciente` (`id_paciente`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_atendimento_status` FOREIGN KEY (`id_status`) REFERENCES `status_atendimento` (`id_status`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `ck_atendimento_tipo_entrada` CHECK (`tipo_entrada` in ('E','A','B','T')),
  CONSTRAINT `ck_atendimento_identificacao` CHECK (`id_paciente` is not null or `id_cadastro_provisorio` is not null)
) ENGINE=InnoDB AUTO_INCREMENT=2202 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

