DROP TABLE IF EXISTS `cadastro_provisorio`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `cadastro_provisorio` (
  `id_cadastro_provisorio` int(11) NOT NULL AUTO_INCREMENT,
  `identificacao` varchar(120) NOT NULL,
  `sexo_aparente` char(1) DEFAULT NULL,
  `idade_aparente` smallint(6) DEFAULT NULL,
  `caracteristicas` varchar(255) DEFAULT NULL,
  `local_encontrado` varchar(150) DEFAULT NULL,
  `data_hora_cadastro` datetime NOT NULL DEFAULT current_timestamp(),
  `id_paciente` int(11) DEFAULT NULL,
  `data_identificacao` datetime DEFAULT NULL,
  PRIMARY KEY (`id_cadastro_provisorio`),
  KEY `fk_cadastro_provisorio_paciente` (`id_paciente`),
  CONSTRAINT `fk_cadastro_provisorio_paciente` FOREIGN KEY (`id_paciente`) REFERENCES `paciente` (`id_paciente`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `ck_cadastro_provisorio_sexo_aparente` CHECK (`sexo_aparente` in ('M','F','I')),
  CONSTRAINT `ck_cadastro_provisorio_idade_aparente` CHECK (`idade_aparente` between 0 and 130)
) ENGINE=InnoDB AUTO_INCREMENT=121 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

