DROP TABLE IF EXISTS `contato`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `contato` (
  `id_contato` int(11) NOT NULL AUTO_INCREMENT,
  `id_paciente` int(11) DEFAULT NULL,
  `id_funcionario` int(11) DEFAULT NULL,
  `tipo` char(1) NOT NULL,
  `valor` varchar(120) NOT NULL,
  `nome_contato` varchar(120) DEFAULT NULL,
  `principal` char(1) NOT NULL DEFAULT 'N',
  PRIMARY KEY (`id_contato`),
  KEY `fk_contato_paciente` (`id_paciente`),
  KEY `fk_contato_funcionario` (`id_funcionario`),
  CONSTRAINT `fk_contato_funcionario` FOREIGN KEY (`id_funcionario`) REFERENCES `funcionario` (`id_funcionario`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_contato_paciente` FOREIGN KEY (`id_paciente`) REFERENCES `paciente` (`id_paciente`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `ck_contato_tipo` CHECK (`tipo` in ('C','F','E')),
  CONSTRAINT `ck_contato_principal` CHECK (`principal` in ('S','N')),
  CONSTRAINT `ck_contato_dono` CHECK (`id_paciente` is not null and `id_funcionario` is null or `id_paciente` is null and `id_funcionario` is not null)
) ENGINE=InnoDB AUTO_INCREMENT=4091 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
