DROP TABLE IF EXISTS `contraindicacao`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `contraindicacao` (
  `id_contraindicacao` int(11) NOT NULL AUTO_INCREMENT,
  `id_historico` int(11) NOT NULL,
  `descricao` varchar(255) NOT NULL,
  `motivo` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id_contraindicacao`),
  KEY `fk_contraindicacao_historico` (`id_historico`),
  CONSTRAINT `fk_contraindicacao_historico` FOREIGN KEY (`id_historico`) REFERENCES `historico_clinico` (`id_historico`) ON DELETE NO ACTION ON UPDATE NO ACTION
) ENGINE=InnoDB AUTO_INCREMENT=530 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
