CREATE TABLE `equipamento` (
  `id_equipamento` int(11) NOT NULL AUTO_INCREMENT,
  `id_local` int(11) NOT NULL,
  `nome` varchar(100) NOT NULL,
  `numero_patrimonio` varchar(20) NOT NULL,
  `status` char(1) NOT NULL DEFAULT 'D',
  PRIMARY KEY (`id_equipamento`),
  UNIQUE KEY `numero_patrimonio` (`numero_patrimonio`),
  KEY `fk_equipamento_local` (`id_local`),
  CONSTRAINT `fk_equipamento_local` FOREIGN KEY (`id_local`) REFERENCES `local` (`id_local`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `ck_equipamento_status` CHECK (`status` in ('D','U','M','I'))
) ENGINE=InnoDB AUTO_INCREMENT=236 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
