DROP TABLE IF EXISTS `internacao`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `internacao` (
  `id_internacao` int(11) NOT NULL AUTO_INCREMENT,
  `id_atendimento` int(11) NOT NULL,
  `id_funcionario` int(11) NOT NULL,
  `data_hora_entrada` datetime NOT NULL DEFAULT current_timestamp(),
  `data_hora_saida` datetime DEFAULT NULL,
  `motivo` varchar(255) NOT NULL,
  `tipo` char(1) NOT NULL,
  `status` char(1) NOT NULL DEFAULT 'A',
  PRIMARY KEY (`id_internacao`),
  UNIQUE KEY `id_atendimento` (`id_atendimento`),
  KEY `fk_internacao_funcionario` (`id_funcionario`),
  KEY `idx_internacao_status_tipo_datas` (`status`,`tipo`,`data_hora_entrada`,`data_hora_saida`),
  CONSTRAINT `fk_internacao_atendimento` FOREIGN KEY (`id_atendimento`) REFERENCES `atendimento` (`id_atendimento`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_internacao_funcionario` FOREIGN KEY (`id_funcionario`) REFERENCES `funcionario` (`id_funcionario`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `ck_internacao_tipo` CHECK (`tipo` in ('C','R','U')),
  CONSTRAINT `ck_internacao_status` CHECK (`status` in ('A','E')),
  CONSTRAINT `ck_internacao_datas` CHECK (`data_hora_saida` is null or `data_hora_saida` >= `data_hora_entrada`)
) ENGINE=InnoDB AUTO_INCREMENT=324 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

