--
-- Table structure for table `ocupacao`
--

DROP TABLE IF EXISTS `ocupacao`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ocupacao` (
  `id_ocupacao` int(11) NOT NULL AUTO_INCREMENT,
  `id_internacao` int(11) NOT NULL,
  `id_leito` int(11) NOT NULL,
  `data_hora_entrada` datetime NOT NULL DEFAULT current_timestamp(),
  `data_hora_saida` datetime DEFAULT NULL,
  PRIMARY KEY (`id_ocupacao`),
  KEY `fk_ocupacao_internacao` (`id_internacao`),
  KEY `fk_ocupacao_leito` (`id_leito`),
  CONSTRAINT `fk_ocupacao_internacao` FOREIGN KEY (`id_internacao`) REFERENCES `internacao` (`id_internacao`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_ocupacao_leito` FOREIGN KEY (`id_leito`) REFERENCES `leito` (`id_leito`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `ck_ocupacao_datas` CHECK (`data_hora_saida` is null or `data_hora_saida` >= `data_hora_entrada`)
) ENGINE=InnoDB AUTO_INCREMENT=367 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

