/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER trg_ocupar_leito
AFTER INSERT ON ocupacao
FOR EACH ROW
BEGIN

    UPDATE leito
    SET status = 'O'
    WHERE id_leito = NEW.id_leito;

END */;;
