--
-- Table structure for table `paciente`
--

DROP TABLE IF EXISTS `paciente`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `paciente` (
  `id_paciente` int(11) NOT NULL AUTO_INCREMENT,
  `nome` varchar(120) NOT NULL,
  `cpf` char(11) NOT NULL,
  `data_nasc` date NOT NULL,
  `sexo` char(1) NOT NULL,
  `nome_mae` varchar(120) DEFAULT NULL,
  `cartao_sus` char(15) DEFAULT NULL,
  `tipo_sanguineo` varchar(3) DEFAULT NULL,
  `id_convenio` int(11) DEFAULT NULL,
  `numero_carteirinha` varchar(20) DEFAULT NULL,
  `data_cadastro` datetime NOT NULL DEFAULT current_timestamp(),
  `status` char(1) NOT NULL DEFAULT 'A',
  PRIMARY KEY (`id_paciente`),
  UNIQUE KEY `cpf` (`cpf`),
  UNIQUE KEY `cartao_sus` (`cartao_sus`),
  KEY `fk_paciente_convenio` (`id_convenio`),
  CONSTRAINT `fk_paciente_convenio` FOREIGN KEY (`id_convenio`) REFERENCES `convenio` (`id_convenio`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `ck_paciente_sexo` CHECK (`sexo` in ('M','F','O')),
  CONSTRAINT `ck_paciente_tipo_sanguineo` CHECK (`tipo_sanguineo` in ('A+','A-','B+','B-','AB+','AB-','O+','O-')),
  CONSTRAINT `ck_paciente_status` CHECK (`status` in ('A','I','O'))
) ENGINE=InnoDB AUTO_INCREMENT=1803 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

