--
-- Table structure for table `resultado_exame`
--

DROP TABLE IF EXISTS `resultado_exame`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `resultado_exame` (
  `id_resultado` int(11) NOT NULL AUTO_INCREMENT,
  `id_solicitacao` int(11) NOT NULL,
  `id_funcionario` int(11) NOT NULL,
  `data_hora_coleta` datetime DEFAULT NULL,
  `data_hora_resultado` datetime NOT NULL DEFAULT current_timestamp(),
  `resultado` text NOT NULL,
  `arquivo_laudo` varchar(255) DEFAULT NULL,
  `situacao` char(1) NOT NULL,
  PRIMARY KEY (`id_resultado`),
  UNIQUE KEY `id_solicitacao` (`id_solicitacao`),
  KEY `fk_resultado_exame_funcionario` (`id_funcionario`),
  KEY `idx_resultado_solic_sit_data` (`id_solicitacao`,`situacao`,`data_hora_resultado`),
  CONSTRAINT `fk_resultado_exame_funcionario` FOREIGN KEY (`id_funcionario`) REFERENCES `funcionario` (`id_funcionario`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_resultado_exame_solicitacao` FOREIGN KEY (`id_solicitacao`) REFERENCES `solicitacao` (`id_solicitacao`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `ck_resultado_exame_situacao` CHECK (`situacao` in ('N','A','C'))
) ENGINE=InnoDB AUTO_INCREMENT=4670 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

