INSERT INTO `resultado_exame` VALUES (1,2,153,'2026-04-01 07:15:18','2026-04-01 07:21:18','Ritmo sinusal, FC 95 bpm, eixo elétrico normal. Sem alterações de repolarização ventricular.','laudos/2026/04/CARD-000002.pdf','N'),(2,7,246,'2026-04-01 09:54:39','2026-04-01 10:37:39','Creatinina: 1,19 mg/dL (VR: 0,6 a 1,3 mg/dL).','laudos/2026/04/LAB-000007.pdf','N'),(3,8,190,'2026-04-01 09:55:55','2026-04-01 10:41:55','Densidade 1,015; pH 5,5; proteínas, glicose e cetonas ausentes; leucócitos 2.000/mL; hemácias 2.000/mL; nitrito negativo.','laudos/2026/04/URI-000008.pdf','N'),(4,6,60,'2026-04-01 09:40:27','2026-04-01 10:50:27','Potássio: 3,9 mEq/L (VR: 3,5 a 5,1 mEq/L).','laudos/2026/04/LAB-000006.pdf','N'),(5,5,60,'2026-04-01 09:41:11','2026-04-01 10:53:11','Ureia: 42 mg/dL (VR: 15 a 45 mg/dL).','laudos/2026/04/LAB-000005.pdf','N'),(6,12,121,'2026-04-01 10:04:18','2026-04-01 11:16:18','Glicemia: 283 mg/dL (VR: 70 a 99 mg/dL). Hiperglicemia.','laudos/2026/04/LAB-000012.pdf','A'),(7,4,60,'2026-04-01 10:03:09','2026-04-01 11:32:09','Hemoglobina 13,2 g/dL; hematócrito 38,5%; leucócitos 8278/mm³ com diferencial normal; plaquetas 233.000/mm³. Hemograma sem alterações.','laudos/2026/04/LAB-000004.pdf','N'),(8,11,206,'2026-04-01 10:03:15','2026-04-01 11:47:15','Sódio: 136 mEq/L (VR: 135 a 145 mEq/L).','laudos/2026/04/LAB-000011.pdf','N'),(9,22,45,'2026-04-01 11:38:40','2026-04-01 12:09:40','Fratura da extremidade distal do rádio direito, com desvio dorsal (fratura de Colles).','laudos/2026/04/IMG-000022.pdf','A'),(10,19,60,'2026-04-01 11:10:42','2026-04-01 12:12:42','Glicemia: 58 mg/dL (VR: 70 a 99 mg/dL). Valor crítico comunicado ao médico.','laudos/2026/04/LAB-000019.pdf','C'),(11,18,121,'2026-04-01 11:14:30','2026-04-01 12:14:30','Sódio: 140 mEq/L (VR: 135 a 145 mEq/L).','laudos/2026/04/LAB-000018.pdf','N'),(12,32,246,'2026-04-01 12:22:47','2026-04-01 12:48:47','Reagente (positivo) para antígeno NS1 da dengue.',NULL,'A'),(13,29,206,'2026-04-01 12:42:06','2026-04-01 13:26:06','H