--
-- Table structure for table `sinais_vitais`
--

DROP TABLE IF EXISTS `sinais_vitais`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sinais_vitais` (
  `id_sinais_vitais` int(11) NOT NULL AUTO_INCREMENT,
  `id_atendimento` int(11) NOT NULL,
  `id_funcionario` int(11) NOT NULL,
  `data_hora` datetime NOT NULL DEFAULT current_timestamp(),
  `pressao_sistolica` smallint(6) DEFAULT NULL,
  `pressao_diastolica` smallint(6) DEFAULT NULL,
  `frequencia_cardiaca` smallint(6) DEFAULT NULL,
  `frequencia_respiratoria` tinyint(4) DEFAULT NULL,
  `temperatura` decimal(4,1) DEFAULT NULL,
  `saturacao_o2` tinyint(4) DEFAULT NULL,
  `glicemia` smallint(6) DEFAULT NULL,
  `escala_dor` tinyint(4) DEFAULT NULL,
  PRIMARY KEY (`id_sinais_vitais`),
  KEY `fk_sinais_vitais_atendimento` (`id_atendimento`),
  KEY `fk_sinais_vitais_funcionario` (`id_funcionario`),
  KEY `idx_sinais_data_alerta` (`data_hora`,`saturacao_o2`,`pressao_sistolica`,`temperatura`,`id_atendimento`),
  CONSTRAINT `fk_sinais_vitais_atendimento` FOREIGN KEY (`id_atendimento`) REFERENCES `atendimento` (`id_atendimento`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_sinais_vitais_funcionario` FOREIGN KEY (`id_funcionario`) REFERENCES `funcionario` (`id_funcionario`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `ck_sinais_vitais_pressao_sistolica` CHECK (`pressao_sistolica` between 40 and 300),
  CONSTRAINT `ck_sinais_vitais_pressao_diastolica` CHECK (`pressao_diastolica` between 20 and 200),
  CONSTRAINT `ck_sinais_vitais_frequencia_cardiaca` CHECK (`frequencia_cardiaca` between 20 and 250),
  CONSTRAINT `ck_sinais_vitais_frequencia_respiratoria` CHECK (`frequencia_respiratoria` between 5 and 80),
  CONSTRAINT `ck_sinais_vitais_temperatura` CHECK (`temperatura` between 30 and 45),
  CONSTRAINT `ck_sinais_vitais_saturacao_o2` CHECK (`saturacao_o2` between 50 and 100),
  CONSTRAINT `ck_sinais_vitais_glicemia` CHECK (`glicemia` between 20 and 800),
  CONSTRAINT `ck_sinais_vitais_escala_dor` CHECK (`escala_dor` between 0 and 10)
) ENGINE=InnoDB AUTO_INCREMENT=5990 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `sinais_vitais`
--

LOCK TABLES `sinais_vitais` WRITE;
/*!40000 ALTER TABLE `sinais_vitais` DISABLE KEYS */;
