--
-- Table structure for table `solicitacao`
--

DROP TABLE IF EXISTS `solicitacao`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `solicitacao` (
  `id_solicitacao` int(11) NOT NULL AUTO_INCREMENT,
  `id_atendimento` int(11) NOT NULL,
  `id_funcionario` int(11) NOT NULL,
  `tipo` char(1) NOT NULL,
  `id_procedimento` int(11) DEFAULT NULL,
  `id_exame` int(11) DEFAULT NULL,
  `id_insumo` int(11) DEFAULT NULL,
  `quantidade` smallint(6) NOT NULL DEFAULT 1,
  `prioridade` char(1) NOT NULL DEFAULT 'N',
  `status` char(1) NOT NULL DEFAULT 'P',
  `data_hora` datetime NOT NULL DEFAULT current_timestamp(),
  `observacao` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id_solicitacao`),
  KEY `fk_solicitacao_atendimento` (`id_atendimento`),
  KEY `fk_solicitacao_funcionario` (`id_funcionario`),
  KEY `fk_solicitacao_procedimento` (`id_procedimento`),
  KEY `fk_solicitacao_exame` (`id_exame`),
  KEY `fk_solicitacao_insumo` (`id_insumo`),
  KEY `idx_solicitacao_prio_exame_data` (`prioridade`,`id_exame`,`data_hora`),
  CONSTRAINT `fk_solicitacao_atendimento` FOREIGN KEY (`id_atendimento`) REFERENCES `atendimento` (`id_atendimento`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_solicitacao_exame` FOREIGN KEY (`id_exame`) REFERENCES `exame` (`id_exame`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_solicitacao_funcionario` FOREIGN KEY (`id_funcionario`) REFERENCES `funcionario` (`id_funcionario`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_solicitacao_insumo` FOREIGN KEY (`id_insumo`) REFERENCES `insumo` (`id_insumo`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_solicitacao_procedimento` FOREIGN KEY (`id_procedimento`) REFERENCES `procedimento` (`id_procedimento`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `ck_solicitacao_tipo` CHECK (`tipo` in ('P','E','I')),
  CONSTRAINT `ck_solicitacao_quantidade` CHECK (`quantidade` >= 1),
  CONSTRAINT `ck_solicitacao_prioridade` CHECK (`prioridade` in ('N','U')),
  CONSTRAINT `ck_solicitacao_status` CHECK (`status` in ('P','E','R','C')),
  CONSTRAINT `ck_solicitacao_item` CHECK (`tipo` = 'P' and `id_procedimento` is not null and `id_exame` is null and `id_insumo` is null or `tipo` = 'E' and `id_exame` is not null and `id_procedimento` is null and `id_insumo` is null or `tipo` = 'I' and `id_insumo` is not null and `id_procedimento` is null and `id_exame` is null)
) ENGINE=InnoDB AUTO_INCREMENT=11550 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

