/*!50003 DROP PROCEDURE IF EXISTS `sp_encerrar_internacao` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ZERO_IN_DATE,NO_ZERO_DATE,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_encerrar_internacao`(
    IN p_id_internacao INT
)
BEGIN

    DECLARE v_status CHAR(1);

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    START TRANSACTION;

    SELECT status
    INTO v_status
    FROM internacao
    WHERE id_internacao = p_id_internacao
    FOR UPDATE;

    IF v_status <> 'A' THEN

        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Internacao inexistente ou ja encerrada';

    END IF;

    UPDATE internacao
    SET
        data_hora_saida = CURRENT_TIMESTAMP,
        status = 'E'
    WHERE id_internacao = p_id_internacao;

    UPDATE ocupacao
    SET data_hora_saida = CURRENT_TIMESTAMP
    WHERE id_internacao = p_id_internacao
      AND data_hora_saida IS NULL;

    COMMIT;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `sp_registrar_movimentacao_estoque` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ZERO_IN_DATE,NO_ZERO_DATE,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_registrar_movimentacao_estoque`(
    IN p_id_insumo INT,
    IN p_id_estoque INT,
    IN p_id_funcionario INT,
    IN p_tipo CHAR(1),
    IN p_quantidade INT,
    IN p_lote VARCHAR(30),
    IN p_data_validade DATE,
    IN p_id_solicitacao INT
)
BEGIN

    IF p_quantidade IS NULL OR p_quantidade < 1 THEN

        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'A quantidade deve ser maior que zero';

    END IF;

    IF p_tipo NOT IN ('E', 'S', 'A') OR p_tipo IS NULL THEN

        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Tipo de movimentacao invalido';

    END IF;

    INSERT INTO movimentacao_estoque (
        id_insumo,
        id_estoque,
        id_funcionario,
        id_solicitacao,
        tipo,
        quantidade,
        lote,
        data_validade
    )
    VALUES (
        p_id_insumo,
        p_id_estoque,
        p_id_funcionario,
        p_id_solicitacao,
        p_tipo,
        p_quantidade,
        p_lote,
        p_data_validade
    );

END ;;
DELIMITER ;
